from itertools import permutations

def is_valid_transition(sigma_s, sigma_next):
    # Condition 1: sigma_next(x1) < sigma_next(x2) => sigma_s(x1) < sigma_s(x2)
    # This is equivalent to: if sigma_s(x1) > sigma_s(x2) then sigma_next(x1) > sigma_next(x2)
    for x1 in range(len(sigma_s)):
        for x2 in range(len(sigma_s)):
            if sigma_s[x1] > sigma_s[x2]:
                if not (sigma_next[x1] > sigma_next[x2]):
                    return False

    # Condition 2: sigma_next(x1+1) < sigma_next(x2+1) => sigma_s(x1) < sigma_s(x2)
    # This is equivalent to: if sigma_s(x1) > sigma_s(x2) then sigma_next(x1+1) > sigma_next(x2+1)
    for x1 in range(len(sigma_s)):
        for x2 in range(len(sigma_s)):
            if sigma_s[x1] > sigma_s[x2]:
                if not (sigma_next[x1+1] > sigma_next[x2+1]):
                    return False
    return True

def find_all_sequences(max_s):
    # sigmas[s] is a list of valid permutations for s
    sigmas = [[] for _ in range(max_s + 1)]
    sigmas[0] = [tuple([0])]

    for s in range(max_s):
        for sigma_s in sigmas[s]:
            for sigma_next in permutations(range(s + 2)):
                if is_valid_transition(sigma_s, sigma_next):
                    sigmas[s+1].append(sigma_next)

    return sigmas

