def solve_detailed():
    results = []
    for s in range(200):
        L = max(0, s - 99)
        R = min(s, 99)
        H = (s * (s + 1) // 2) % 2
        target_n = (1 - H) % 2
        target_m = (s + H - 1) % 2
        count_n = 0
        count_m = 0
        for x in range(L, R + 1):
            if x % 2 == target_n:
                count_n += 1
            if x % 2 == target_m:
                count_m += 1
        if count_n != count_m:
            results.append((s, count_n, count_m))
    return results

