    for s in range(2 * limit - 1):
        L_s = max(0, s - (limit - 1))
        R_s = min(s, limit - 1)
        if f_type == 1:
            # H(s) + x is odd
            target_parity = (1 - H(s)) % 2
            def count_in_range(L, R, p):
                if L > R: return 0
                def count_upto(N, parity):
                    if N < 0: return 0
                    if N < parity: return 0
                    return (N - parity) // 2 + 1
                return count_upto(R, p) - count_upto(L - 1, p)
            total_count += count_in_range(L_s, R_s, target_parity)
        else:
            # H(s) + (s-x) is odd
            target_parity = (s - (1 - H(s))) % 2
            def count_in_range(L, R, p):
                if L > R: return 0
                def count_upto(N, parity):
                    if N < 0: return 0
                    if N < parity: return 0
                    return (N - parity) // 2 + 1
                return count_upto(R, p) - count_upto(L - 1, p)
            total_count += count_in_range(L_s, R_s, target_parity)
    return total_count

