def count_odd(s, mode):
    # mode 1: f(x,y) = H(s) + x
    # mode 2: f(x,y) = H(s) + s - x
    L = max(0, s - 99)
    R = min(s, 99)
    count = 0
    for x in range(L, R + 1):
        if mode == 1:
            val = H(s) + x
        else:
            val = H(s) + (s - x)
        if val % 2 == 1:
            count += 1
    return count

