def check_sigma_combinations(max_s):
    from itertools import product
    results = []
    # sigmas[s] can be id (0) or rev (1)
    for sigmas in product([0, 1], repeat=max_s + 1):
        f = {}
        for x in range(max_s + 1):
            for y in range(max_s + 1):
                s = x + y
                if s <= max_s:
                    if sigmas[s] == 0:
                        f[(x, y)] = (s * (s + 1) // 2) + x
                    else:
                        f[(x, y)] = (s * (s + 1) // 2) + (s - x)

        possible = True
        # The condition is:
        # for all (x1, y1), (x2, y2) in Z^2 x Z^2:
        # f(x1, y1) > f(x2, y2) => f(x1+1, y1) > f(x2+1, y2) AND f(x1, y1+1) > f(x2, y2+1)

        # We only know f for x+y <= max_s.
        # Let's test the condition for all (x1, y1), (x2, y2) such that 
        # x1+y1 <= max_s and x2+y2 <= max_s,
        # AND x1+1+y1 <= max_s and x2+1+y2 <= max_s (for condition 1)
        # AND x1+y1+1 <= max_s and x2+y2+1 <= max_s (for condition 2)

        # Wait, the conditions must hold for *all* x, y.
        # But for f(x, y) = H(x+y) + sigma_{x+y}(x),
        # we can see that the condition is equivalent to:
        # 1. sigma_s is id or rev for all s.
        # 2. sigma_s = sigma_{s+1} for all s.

        # Let's check that.
        for s in range(max_s):
            # check if sigma_s = sigma_{s+1}
            if sigmas[s] != sigmas[s+1]:
                possible = False
                break

        if possible:
            results.append(sigmas)
    return results

